 lateral_v22:{theme:"lateral",icon:"💡",file:"SIDE-22",seal:"ASSUMPTION BREAKER",title:{"ar": "مختبر التفكير الجانبي", "en": "Lateral Lab", "zh": "横向思维实验室", "hi": "लेटरल लैब", "es": "Laboratorio de Pensamiento Lateral", "fr": "Labo de Pensée Latérale", "fa": "آزمایشگاه تفکر جانبی"},kicker:{"ar": "غرفة التفكير الجانبي", "en": "Lateral Thinking Room", "zh": "横向思维密室", "hi": "पार्श्व चिंतन कक्ष", "es": "Sala de Pensamiento Lateral", "fr": "Salle de Pensée Latérale", "fa": "اتاق تفکر جانبی"},line:{"ar": "أصعب جزء في اللغز هو الافتراض الذي لم تنتبه إليه.", "en": "The hardest part of the puzzle is the assumption you never noticed.", "zh": "谜题最难的部分,是你从未注意到的那个假设。", "hi": "पहेली का सबसे मुश्किल हिस्सा वह धारणा है जिसे आपने नोटिस नहीं किया।", "es": "La parte más difícil del rompecabezas es la suposición que nunca notaste.", "fr": "La partie la plus difficile de l'énigme est l'hypothèse que vous n'avez jamais remarquée.", "fa": "سخت‌ترین بخش معما، فرضیه‌ای است که هرگز متوجه آن نشدی."},steps:[{"ar": ["تثبيت المشهد", "كل معلومة تبدو عادية."], "en": ["Setting the Scene", "Every piece of information looks ordinary."], "zh": ["设定场景", "每条信息看起来都很普通。"], "hi": ["दृश्य स्थापित करना", "हर जानकारी सामान्य लगती है।"], "es": ["Fijando la escena", "Cada dato parece normal."], "fr": ["Installer la scène", "Chaque information semble ordinaire."], "fa": ["برپایی صحنه", "هر اطلاعاتی عادی به‌نظر می‌رسد."]}, {"ar": ["كسر الافتراض", "هناك تفسير آخر."], "en": ["Breaking the Assumption", "There's another explanation."], "zh": ["打破假设", "还有另一种解释。"], "hi": ["धारणा तोड़ना", "एक और स्पष्टीकरण है।"], "es": ["Rompiendo la suposición", "Hay otra explicación."], "fr": ["Briser l'hypothèse", "Il y a une autre explication."], "fa": ["شکستن فرضیه", "توضیح دیگری هم هست."]}, {"ar": ["تغيير زاوية النظر", "الحل يظهر عندما تغيّر السؤال."], "en": ["Changing the Angle", "The solution appears when you change the question."], "zh": ["转换视角", "当你改变问题时,答案就出现了。"], "hi": ["नज़रिया बदलना", "जब आप सवाल बदलते हैं तो हल दिखता है।"], "es": ["Cambiando el ángulo", "La solución aparece cuando cambias la pregunta."], "fr": ["Changer d'angle", "La solution apparaît quand vous changez la question."], "fa": ["تغییر زاویه نگاه", "راه‌حل وقتی ظاهر می‌شود که سوال را تغییر دهی."]}, {"ar": ["فتح الباب", "أثبت أنك لا تفكر بخط واحد."], "en": ["Opening the Door", "Prove you don't think in a straight line."], "zh": ["开门", "证明你不是只会直线思考。"], "hi": ["दरवाज़ा खोलना", "साबित करें आप सीधी-सादी सोच में बंधे नहीं हैं।"], "es": ["Abriendo la puerta", "Demuestra que no piensas en línea recta."], "fr": ["Ouvrir la porte", "Prouvez que vous ne pensez pas en ligne droite."], "fa": ["بازکردن در", "ثابت کن که فقط در یک خط فکر نمی‌کنی."]}],roomHint:{"ar": "اسأل: ماذا أفترض دون دليل؟", "en": "Ask yourself: what am I assuming without evidence?", "zh": "问自己:我在没有证据的情况下假设了什么?", "hi": "खुद से पूछें: मैं बिना सबूत के क्या मान रहा हूँ?", "es": "Pregúntate: ¿qué estoy suponiendo sin pruebas?", "fr": "Demandez-vous : que suppose-je sans preuve ?", "fa": "از خود بپرس: بدون دلیل چه چیزی را فرض گرفته‌ام؟"}},
