 intro(done,id){this.room=roomDNA(id);this.mode=id;this.active=true;this.phase=1;this.question=1;this.answered=0;const e=this.mount(),r=this.room;document.body.classList.add('zivo-cinematic-active');document.body.dataset.roomTheme=r.theme;e.dataset.roomTheme=r.theme;e.classList.remove('exit');e.classList.add('show');for(const [sel,val] of [['#zce-kicker',r.kicker],['#zce-file',r.file],['#zce-seal',r.seal],['#zce-title',r.title],['#zce-line',r.line],['#zce-bottom-a',r.roomHint]]){const n=e.querySelector(sel);if(n)n.textContent=val}const art=e.querySelector('#zce-room-art');if(art)art.innerHTML=this.art(id,r.theme,r.icon);const status=e.querySelector('#zce-status'),meter=e.querySelector('#zce-meter');let i=0;const run=()=>{if(!this.active)return;if(i>=r.steps.length){e.classList.add('exit');setTimeout(()=>{e.classList.remove('show','exit');document.body.classList.remove('zivo-cinematic-active');delete document.body.dataset.roomTheme;done()},650);return}status.textContent=r.steps[i][0];e.querySelector('#zce-line').textContent=r.steps[i][1];if(meter)meter.style.width=((i+1)/r.steps.length*100)+'%';e.dataset.step=String(i+1);i++;this.introTimer=setTimeout(run,i===r.steps.length?1100:900)};run()},
