const worldFor=id=>{const base=ROOM_WORLD[id]||ROOM_WORLD.iq;const lang=document.documentElement.lang||'ar';if(lang==='ar')return base;const pack=ROOM_WORLD_I18N[lang]?.[id]||ROOM_WORLD_I18N[lang]?.iq;if(!pack)return base;return {...base,label:pack.label,sub:pack.sub,zones:pack.zones,modes:pack.modes,intro:pack.intro}};
const roomMode=(id,i)=>{const w=worldFor(id);return w.modes[i%w.modes.length]};
const roomZone=(id,i)=>{const w=worldFor(id);return w.zones[i%w.zones.length]};

