 async _startInner(id){if(id==='horror')document.body.classList.add('zivo-darkroom-active');else document.body.classList.remove('zivo-darkroom-active');
  if(id==='forensic'){
    this.guest=!user();
    if(window.ZIVOZONE_FORENSIC_CORE?.start)return window.ZIVOZONE_FORENSIC_CORE.start();
    toast(t('forensicPreparing'),'info');
    try{
      const core=await loadForensicCore();
      return core.start();
    }catch(e){
      console.warn('Forensic Lab lazy-load failed:',e);
      toast(t('forensicLoadFailed'),'error');
      return false;
    }
  }
  const b=bank(id);if(!b||!b.questions?.length)return false;this.guest=!user();const count=10;this.run={id,title:text(b.title||b.name||worldFor(id).label),icon:b.icon||'🎯',questions:chooseQuestions(b,count),xp:Number(b.xp)||80,world:worldFor(id),scored:b.nonScored!==true};try{await audio().unlock?.();const ambientMap={iq:'iq',math:'math',science:'science',football:'football',logic:'logic',daily:'daily',strategy:'strategy',memory:'memory',reaction:'reaction'};if(ambientMap[id])await audio().transitionAmbient?.(ambientMap[id]);}catch(e){console.warn('ZIVOZONE challenge audio:',e)}cinema.start(id);cinema.intro(()=>{this.reset();this.maybeShowDuelIntro(()=>this.renderWorldHub())},id);return true},
