  this.activeDuel=duel;
  const m=this.ensure();
  m.innerHTML=`<div class="zrw-duel-intro" dir="${document.documentElement.dir||'rtl'}"><div class="zrw-duel-badge">⚔️</div><h2>${esc(fmt('duelInviteBannerTitle',{name:duel.name}))}</h2><p>${esc(fmt('duelInviteBannerBody',{name:duel.name,score:duel.score,challenge:text(this.run.title)}))}</p><button type="button" class="zrw-duel-start btn btn-primary full">${esc(t('duelInviteStartCta'))}</button></div>`;
