  const gameNames=GAME_NAMES_BY_LANG[lang]||GAME_NAMES_BY_LANG.en;
  const name=gameNames[id]||'World Game';

  let level=1,lives=3,score=0,ended=false,raf=0,timers=[],listeners=[];
  const lerp=(lv,a,b)=>a+(b-a)*(Math.min(MAXLV,Math.max(1,lv))-1)/(MAXLV-1);
  const rint=(a,b)=>Math.floor(a+Math.random()*(b-a+1));
  const clearTimers=()=>{timers.forEach(h=>{clearTimeout(h);clearInterval(h)});timers=[]};
  const clearListeners=()=>{listeners.forEach(([el,ev,fn])=>{try{el.removeEventListener(ev,fn)}catch(_){}});listeners=[]};
  const addTimer=(fn,ms)=>{const h=setTimeout(fn,ms);timers.push(h);return h};
  const addInterval=(fn,ms)=>{const h=setInterval(fn,ms);timers.push(h);return h};
  const addListener=(el,ev,fn)=>{el.addEventListener(ev,fn);listeners.push([el,ev,fn])};
  const stopLoop=()=>{if(raf)cancelAnimationFrame(raf);raf=0};
  const cleanupLevel=()=>{stopLoop();clearTimers();clearListeners()};

  const exitMiniGame=()=>{cleanupLevel();ended=true;document.body.classList.remove('zivo-minigame-active');m.hidden=true;m.innerHTML='';m.className='zwh-mini-board'};
  m.innerHTML=`<div class="zrg-shell" dir="${document.documentElement.dir||'rtl'}"><button type="button" class="zrg-exit" aria-label="${esc(t('miniExitAria'))}">✕</button><div class="zrg-head"><div><span>${esc(t('miniWorldGameLabel'))}</span><h3>${esc(name)}</h3></div><div><b id="zrg-score">0</b><small>${esc(t('miniPointsLabel'))}</small></div></div><div class="zrg-hud"><div class="zrg-pips" id="zrg-pips"></div><div class="zrg-lives" id="zrg-lives"></div></div><div class="zrg-canvas-wrap"><canvas id="zrg-canvas" width="900" height="500" aria-label="${esc(t('miniCanvasAria'))}"></canvas></div><div class="zrg-controls" id="zrg-controls"></div><div class="zrg-status" id="zrg-status"></div></div>`;
  m.querySelector('.zrg-exit').onclick=exitMiniGame;
  const c=m.querySelector('#zrg-canvas'),ctx=c.getContext('2d'),controls=m.querySelector('#zrg-controls'),status=m.querySelector('#zrg-status'),wrap=m.querySelector('.zrg-canvas-wrap'),pipsEl=m.querySelector('#zrg-pips'),livesEl=m.querySelector('#zrg-lives');
  /* V1230.27 fix: the canvas sits inside a dir="rtl" shell, and Canvas2D's fillText bidi-reorders
     numeric/mixed strings (e.g. "0 / 13") when ctx.direction inherits 'rtl' — found live while testing
     the math game, which showed "13 / 0" instead of "0 / 13". Force ltr so every numeric HUD stays in
     the order the code actually writes it, regardless of page language. */
  ctx.direction='ltr';
  // V1230.79 — this used to size the canvas from available WIDTH only (fine in the old small embedded
  // box, which was never taller than its width-driven aspect ratio needed). Now that mobile shows the
  // game full-screen, that left most of the tall phone viewport as dead empty space above/below a
  // comparatively tiny canvas. Also fit to the wrapper's available HEIGHT so the canvas actually fills
  // the screen it was just given, still never upscaled past its native 900x500 resolution.
  const resize=()=>{const maxW=Math.max(300,m.clientWidth-20);const maxH=Math.max(200,(wrap.clientHeight||maxW*500/900)-4);const scale=Math.min(maxW/900,maxH/500,1);const w=900*scale;c.style.width=w+'px';c.style.height=(500*scale)+'px'};
  resize(); addListener(window,'resize',resize);

  const renderHud=()=>{
   pipsEl.innerHTML='';
   for(let i=1;i<=MAXLV;i++){const d=document.createElement('span');d.className='zrg-pip'+(i<level?' done':'')+(i===level?' current':'')+(i===MAXLV?' final':'');pipsEl.appendChild(d)}
   livesEl.innerHTML='';
   for(let i=0;i<3;i++){const s=document.createElement('i');s.textContent='❤';if(i>=lives)s.classList.add('spent');livesEl.appendChild(s)}
   const scoreEl=m.querySelector('#zrg-score'); if(scoreEl)scoreEl.textContent=score;
  };
  const setStatus=(txt)=>{if(status)status.textContent=txt};

  const flash=(kind,titleTxt,sub,after)=>{
   cleanupLevel();
   const f=document.createElement('div');f.className='zrg-flash '+kind;f.innerHTML=`<div><h4>${esc(titleTxt)}</h4><small>${esc(sub)}</small></div>`;
   wrap.appendChild(f);
   addTimer(()=>{f.remove();if(!ended)after&&after()},kind==='lose'?1000:800);
  };

  const finishGame=(won)=>{
   ended=true;cleanupLevel();
   const sub=won?esc(t('miniVictory')):(esc(t('miniReachedLevel'))+' '+level+(level===MAXLV?` <span class="zrg-final-badge">${esc(t('miniFinalLevelTag'))}</span>`:''));
   m.innerHTML=`<div class="zrg-result" dir="${document.documentElement.dir||'rtl'}"><button type="button" class="zrg-exit" aria-label="${esc(t('miniExitAria'))}">✕</button><div class="zrg-result-orb">${this.run.icon||'🎮'}</div><small>${esc(name)}</small><strong>${score}</strong><span>${esc(t('miniPointsLabel'))}</span><p>${sub}</p><button class="zwh-mini-restart">${esc(t('miniPlayAgain'))}</button></div>`;
   m.querySelector('.zrg-exit').onclick=exitMiniGame;
   const btn=m.querySelector('.zwh-mini-restart'); if(btn)btn.onclick=()=>this.startMiniGame();
  };

  const winLevel=(bonus=0)=>{
   score+=10*level+bonus;
   if(level>=MAXLV){renderHud();finishGame(true);return}
   const nextLv=level+1;
   flash('win',t('miniLevelUpTitle'),`${t('miniLevelLabel')} ${nextLv}/${MAXLV}`,()=>{level=nextLv;renderHud();run()});
   renderHud();
  };
  const loseLevel=()=>{
   lives--;renderHud();
   if(lives<=0){finishGame(false);return}
   flash('lose',t('miniTryAgain'),`${t('miniLevelLabel')} ${level}/${MAXLV}`,()=>{run()});
  };

  const point=(e)=>{const r=c.getBoundingClientRect();const cx=(e.touches?e.touches[0].clientX:e.clientX),cy=(e.touches?e.touches[0].clientY:e.clientY);return{x:(cx-r.left)*900/r.width,y:(cy-r.top)*500/r.height}};
  const clear=()=>{ctx.clearRect(0,0,900,500);ctx.fillStyle='#07111d';ctx.fillRect(0,0,900,500)};
  const txt=(label,x,y,size=24,align='center',color='#fff')=>{ctx.fillStyle=color;ctx.font=`800 ${size}px Cairo,Arial`;ctx.textAlign=align;ctx.fillText(label,x,y)};
  const emoji=(label,x,y,size=36)=>{ctx.font=`${size}px sans-serif`;ctx.textAlign='center';ctx.fillText(label,x,y)};
  const button=(label,fn)=>{const b=document.createElement('button');b.className='zrg-btn';b.textContent=label;b.onclick=fn;controls.appendChild(b);return b};
  const countdown=(secs,onTimeout)=>{let left=secs;setStatus(`${t('miniLevelLabel')} ${level}/${MAXLV} — ${Math.ceil(left)}s`);addInterval(()=>{left-=0.1;if(left<=0){onTimeout()}else setStatus(`${t('miniLevelLabel')} ${level}/${MAXLV} — ${Math.ceil(left)}s`)},100)};

  function football(lv){
   const neededPasses=Math.round(lerp(lv,3,8));
   const gapW=lerp(lv,235,88);
   const rowSpeed=lerp(lv,95,245);
   const doubleLine=lv>=7;
   let ballX=450,targetX=450,passed=0,rowY=-20,gapX=rint(80,820-gapW),checked=false,last=performance.now();
   let row2Y=-20-lerp(lv,0,150),gap2X=rint(80,820-gapW),checked2=!doubleLine;
   const onMove=(e)=>{const p=point(e);targetX=Math.max(60,Math.min(840,p.x))};
   addListener(c,'pointerdown',onMove); addListener(c,'pointermove',onMove);
   function frame(ts){
    if(ended)return;
    const dt=Math.min(0.05,(ts-last)/1000); last=ts;
    clear(); ballX+=(targetX-ballX)*0.2; rowY+=rowSpeed*dt; if(doubleLine)row2Y+=rowSpeed*dt;
    ctx.fillStyle='#0d2417'; ctx.fillRect(40,40,820,420);
    ctx.strokeStyle='#2f6e45'; ctx.lineWidth=3; ctx.strokeRect(40,40,820,420);
    ctx.strokeStyle='rgba(255,255,255,.22)'; ctx.lineWidth=2;
    ctx.beginPath(); ctx.moveTo(40,250); ctx.lineTo(860,250); ctx.stroke();
    ctx.beginPath(); ctx.arc(450,250,55,0,Math.PI*2); ctx.stroke();
    ctx.strokeStyle='rgba(255,255,255,.5)'; ctx.strokeRect(330,40,240,36);
    ctx.fillStyle='#b23b4e'; ctx.fillRect(40,rowY,gapX-40,16); ctx.fillRect(gapX+gapW,rowY,860-(gapX+gapW),16);
    if(doubleLine&&row2Y>-30){ctx.fillStyle='#8a2c3c'; ctx.fillRect(40,row2Y,gap2X-40,16); ctx.fillRect(gap2X+gapW,row2Y,860-(gap2X+gapW),16)}
    ctx.fillStyle='#fff'; ctx.beginPath(); ctx.arc(ballX,430,15,0,7); ctx.fill();
    txt(`${passed}/${neededPasses}`,450,30,22);
    if(doubleLine&&!checked2&&row2Y>412&&row2Y<448){
     checked2=true;
     if(!(ballX>gap2X&&ballX<gap2X+gapW)){loseLevel();return}
    }
    if(!checked&&rowY>412&&rowY<448){
     checked=true;
     if(ballX>gapX&&ballX<gapX+gapW){
      passed++; if(passed>=neededPasses){winLevel();return}
      rowY=-20;gapX=rint(80,820-gapW);checked=false;
      if(doubleLine){row2Y=-20-150;gap2X=rint(80,820-gapW);checked2=false}
     }
     else{loseLevel();return}
    }
    if(rowY>500){rowY=-20;gapX=rint(80,820-gapW);checked=false; if(doubleLine){row2Y=-20-150;gap2X=rint(80,820-gapW);checked2=false}}
    raf=requestAnimationFrame(frame);
   }
   raf=requestAnimationFrame(frame);
  }

  function mathGame(lv){
   const k=Math.min(4,Math.round(lerp(lv,2,4)));
   const range=Math.round(lerp(lv,9,28));
   const allowNeg=lv>=8;
   const addends=[]; for(let i=0;i<k;i++)addends.push(allowNeg?(Math.random()<0.5?-1:1)*rint(1,range):rint(1,range));
   const target=addends.reduce((a,b)=>a+b,0);
   const tileCount=Math.round(lerp(lv,7,13));
   const tiles=addends.map(v=>({v,picked:false}));
   while(tiles.length<tileCount){tiles.push({v:allowNeg?(Math.random()<0.5?-1:1)*rint(1,range):rint(1,range),picked:false})}
   tiles.sort(()=>Math.random()-.5);
   const cols=5; tiles.forEach((tl,i)=>{tl.x=140+(i%cols)*160;tl.y=140+Math.floor(i/cols)*110});
   let sum=0;
   const render=()=>{
    clear();
    txt(`${sum} / ${target}`,450,70,40,'center',sum>target&&!allowNeg?'#ff7a90':'#ffd84a');
    tiles.forEach(tl=>{ctx.fillStyle=tl.picked?'#2e6b4a':'#1c2b44';ctx.beginPath();ctx.arc(tl.x,tl.y,38,0,7);ctx.fill();txt(String(tl.v),tl.x,tl.y+8,22)});
   };
   render();
   const click=(e)=>{
    const p=point(e);
    for(const tl of tiles){
     if(!tl.picked&&Math.hypot(p.x-tl.x,p.y-tl.y)<40){
      tl.picked=true; sum+=tl.v; render();
      if(sum===target){winLevel();return}
      if(sum>target&&!allowNeg){sum=0;tiles.forEach(t2=>t2.picked=false);render()}
      break;
     }
    }
   };
   addListener(c,'click',click);
   countdown(lerp(lv,26,13),()=>loseLevel());
  }

  function science(lv){
   const zoneW=lerp(lv,170,46);
   const driftAmp=lerp(lv,70,180);
   const neededHold=lerp(lv,1.6,4.6);
   const zoneCenter=rint(150,750);
   let p=450,vel=0,holdTime=0,holdingLeft=false,holdingRight=false,tLast=performance.now(),tAcc=0;
   const leftBtn=button('◀',()=>{}); const rightBtn=button('▶',()=>{});
   addListener(leftBtn,'pointerdown',()=>holdingLeft=true); addListener(leftBtn,'pointerup',()=>holdingLeft=false); addListener(leftBtn,'pointerleave',()=>holdingLeft=false);
   addListener(rightBtn,'pointerdown',()=>holdingRight=true); addListener(rightBtn,'pointerup',()=>holdingRight=false); addListener(rightBtn,'pointerleave',()=>holdingRight=false);
   function frame(ts){
    if(ended)return;
    const dt=Math.min(0.05,(ts-tLast)/1000); tLast=ts; tAcc+=dt;
    const drift=Math.sin(tAcc*1.3)*driftAmp*dt*0.6+(Math.random()-0.5)*driftAmp*dt*0.4;
    let push=0; if(holdingLeft)push-=260; if(holdingRight)push+=260;
    vel+=(drift+push)*dt; vel*=0.92; p+=vel*dt; p=Math.max(100,Math.min(800,p));
    const inZone=Math.abs(p-zoneCenter)<zoneW/2;
    if(inZone)holdTime+=dt; else holdTime=Math.max(0,holdTime-dt*1.5);
    clear();
    ctx.fillStyle='#16283a'; ctx.fillRect(100,230,700,50);
    ctx.fillStyle='rgba(255,216,74,.35)'; ctx.fillRect(zoneCenter-zoneW/2,230,zoneW,50);
    ctx.fillStyle=inZone?'#5de0b0':'#ff7a90'; ctx.beginPath(); ctx.arc(p,255,14,0,7); ctx.fill();
    const barW=700*Math.min(1,holdTime/neededHold);
    ctx.fillStyle='#1c2b44'; ctx.fillRect(100,310,700,16);
    ctx.fillStyle='var(--gold-fallback,#ffd84a)'; ctx.fillRect(100,310,barW,16);
    if(holdTime>=neededHold){winLevel();return}
    raf=requestAnimationFrame(frame);
   }
   raf=requestAnimationFrame(frame);
   countdown(lerp(lv,24,16),()=>loseLevel());
  }

  function memory(lv){
   const len=Math.round(lerp(lv,3,11));
   const colors=['#ff6b6b','#5de0b0','#5aa7ff','#ffe066','#c792ff','#ff9f5b'];
   const n=Math.min(colors.length,Math.round(lerp(lv,4,6)));
   const seq=[]; for(let i=0;i<len;i++)seq.push(rint(0,n-1));
   const boxW=820/n;
   const drawBoard=(hl=-1)=>{clear(); for(let i=0;i<n;i++){ctx.fillStyle=i===hl?'#fff':colors[i];ctx.fillRect(40+i*boxW,200,boxW-8,160)}};
   drawBoard(); setStatus(t('miniWatch'));
   let step=0;
   const showStep=()=>{
    if(ended)return;
    if(step>=seq.length){startInput();return}
    drawBoard(seq[step]);
    addTimer(()=>{if(ended)return;drawBoard(-1);addTimer(()=>{step++;showStep()},150)},lerp(lv,480,230));
   };
   addTimer(()=>showStep(),500);
   function startInput(){
    drawBoard(); setStatus(t('miniRepeat'));
    let inputIdx=0;
    const click=(e)=>{
     const p=point(e);
     const i=Math.floor((p.x-40)/boxW);
     if(i<0||i>=n||p.y<200||p.y>360)return;
     if(i===seq[inputIdx]){inputIdx++; if(inputIdx>=seq.length){winLevel()}}
     else{loseLevel()}
    };
    addListener(c,'click',click);
   }
  }

  function logic(lv){
   const colors=['#ff6b6b','#5de0b0','#5aa7ff','#ffe066','#c792ff','#ff9f5b','#ff8fd1','#8fe3ff'];
   const codeLen=Math.round(lerp(lv,3,6));
   const numColors=Math.round(lerp(lv,4,8));
   const maxGuesses=Math.round(lerp(lv,10,5));
   const code2=[]; for(let i=0;i<codeLen;i++)code2.push(rint(0,numColors-1));
   let guesses=0,current=[],history=[];
   const paletteY=440;
   const renderBoard=()=>{
    clear();
    txt(`${guesses+1}/${maxGuesses}`,450,30,18);
    history.forEach((h,ri)=>{
     h.guess.forEach((cIdx,ci)=>{ctx.fillStyle=colors[cIdx];ctx.beginPath();ctx.arc(150+ci*45,70+ri*34,13,0,7);ctx.fill()});
     txt(`●${h.black} ○${h.white}`,760,76+ri*34,15,'left','#9aa6c0');
    });
    const rowY=70+history.length*34;
    for(let i=0;i<codeLen;i++){
     ctx.strokeStyle='#546'; ctx.lineWidth=2; ctx.beginPath(); ctx.arc(150+i*45,rowY,13,0,7); ctx.stroke();
     if(current[i]!==undefined){ctx.fillStyle=colors[current[i]];ctx.beginPath();ctx.arc(150+i*45,rowY,13,0,7);ctx.fill()}
    }
    for(let i=0;i<numColors;i++){ctx.fillStyle=colors[i];ctx.beginPath();ctx.arc(120+i*70,paletteY,20,0,7);ctx.fill()}
   };
   const paletteClick=(e)=>{
    const p=point(e);
    for(let i=0;i<numColors;i++){const cx=120+i*70; if(Math.hypot(p.x-cx,p.y-paletteY)<22){if(current.length<codeLen){current.push(i);renderBoard()}return}}
   };
   addListener(c,'click',paletteClick);
   button(t('miniConfirm'),()=>{
    if(current.length<codeLen)return;
    let black=0; const usedCode=[...code2],usedGuess=[...current];
    for(let i=0;i<codeLen;i++)if(usedGuess[i]===usedCode[i]){black++;usedCode[i]=usedGuess[i]=-2}
    let white=0;
    for(let i=0;i<codeLen;i++){if(usedGuess[i]===-2)continue;const idx=usedCode.indexOf(usedGuess[i]);if(idx!==-1){white++;usedCode[idx]=-3}}
    history.push({guess:[...current],black,white}); guesses++;
    if(black===codeLen){winLevel();return}
    current=[];
    if(guesses>=maxGuesses){loseLevel();return}
    renderBoard();
   });
   button(t('miniClear'),()=>{current=[];renderBoard()});
   renderBoard();
  }

  function pattern(lv){
   const gridN=Math.round(lerp(lv,3,5));
   const total=gridN*gridN;
   const oddIndex=rint(0,total-1);
   const baseSpeed=1.0;
   const oddSpeed=baseSpeed*(lv<5?1.8:1.22);
   const cell=700/gridN;
   let t0=performance.now();
   function frame(ts){
    if(ended)return;
    const dt=(ts-t0)/1000;
    clear();
    for(let i=0;i<total;i++){
     const r=Math.floor(i/gridN),cI=i%gridN;
     const x=100+cI*cell+cell/2,y=80+r*cell+cell/2;
     const speed=i===oddIndex?oddSpeed:baseSpeed;
     ctx.save(); ctx.translate(x,y); ctx.rotate(dt*speed*4);
     ctx.fillStyle='#4fd3ff'; ctx.fillRect(-cell*0.28,-cell*0.1,cell*0.56,cell*0.2);
     ctx.restore();
    }
    raf=requestAnimationFrame(frame);
   }
   raf=requestAnimationFrame(frame);
   const click=(e)=>{
    const p=point(e); const cI=Math.floor((p.x-100)/cell),r=Math.floor((p.y-80)/cell);
    if(cI<0||cI>=gridN||r<0||r>=gridN)return;
    const i=r*gridN+cI; if(i===oddIndex)winLevel(); else loseLevel();
   };
   addListener(c,'click',click);
   countdown(lerp(lv,7,3),()=>loseLevel());
  }

