  function focus(lv){
   const decoyCount=Math.round(lerp(lv,10,34));
   const hueDiff=lerp(lv,60,15);
   const baseHue=rint(0,360);
   const target={x:rint(100,800),y:rint(100,400),vx:rint(-60,60)||40,vy:rint(-60,60)||40};
   const decoys=[]; for(let i=0;i<decoyCount;i++)decoys.push({x:rint(100,800),y:rint(100,400),vx:rint(-60,60)||30,vy:rint(-60,60)||30});
   let t0=performance.now();
   function frame(ts){
    if(ended)return;
    const dt=Math.min(0.05,(ts-t0)/1000); t0=ts;
    const bounce=(o)=>{o.x+=o.vx*dt;o.y+=o.vy*dt;if(o.x<30||o.x>870)o.vx*=-1;if(o.y<30||o.y>470)o.vy*=-1};
    bounce(target); decoys.forEach(bounce);
    clear();
    decoys.forEach(o=>{ctx.fillStyle=`hsl(${baseHue+hueDiff},70%,55%)`;ctx.beginPath();ctx.arc(o.x,o.y,16,0,7);ctx.fill()});
    ctx.fillStyle=`hsl(${baseHue},70%,55%)`; ctx.beginPath(); ctx.arc(target.x,target.y,16,0,7); ctx.fill();
    raf=requestAnimationFrame(frame);
   }
   raf=requestAnimationFrame(frame);
   const click=(e)=>{
    const p=point(e);
    if(Math.hypot(p.x-target.x,p.y-target.y)<22){winLevel();return}
    for(const o of decoys){if(Math.hypot(p.x-o.x,p.y-o.y)<22){loseLevel();return}}
   };
   addListener(c,'click',click);
   countdown(lerp(lv,8,3.2),()=>loseLevel());
  }

  function strategy(lv){
   const blipCount=Math.round(lerp(lv,4,10));
   const topK=Math.max(1,Math.round(blipCount*0.4));
   const blips=[]; for(let i=0;i<blipCount;i++)blips.push({x:rint(100,800),y:rint(100,420),pri:Math.random(),handled:false});
   blips.sort((a,b)=>b.pri-a.pri);
   const targetSet=new Set(blips.slice(0,topK));
   let correctHits=0,wrongHits=0;
   const render=()=>{
    clear();
    txt(`${correctHits}/${topK}`,450,40,22);
    blips.forEach(b=>{const r=14+b.pri*18;ctx.fillStyle=b.handled?'#2e6b4a':`rgba(255,${120+b.pri*100},80,${0.6+b.pri*0.4})`;ctx.beginPath();ctx.arc(b.x,b.y,r,0,7);ctx.fill()});
   };
   render();
   const click=(e)=>{
    const p=point(e);
    for(const b of blips){
     if(b.handled)continue;
     const r=14+b.pri*18;
     if(Math.hypot(p.x-b.x,p.y-b.y)<r){
      b.handled=true; if(targetSet.has(b))correctHits++; else wrongHits++; render();
      if(correctHits>=topK){winLevel();return}
      if(wrongHits>=2){loseLevel();return}
      break;
     }
    }
   };
   addListener(c,'click',click);
   countdown(lerp(lv,9,4),()=>loseLevel());
  }

  function probability(lv){
   const winArc=lerp(lv,110,26)*Math.PI/180;
   const spinSpeed=lerp(lv,1.4,4.2);
   const winStart=Math.random()*Math.PI*2;
   let angle=0,stopped=false,t0=performance.now();
   function frame(ts){
    if(ended)return;
    const dt=(ts-t0)/1000; t0=ts;
    if(!stopped)angle+=spinSpeed*dt;
    clear();
    ctx.save(); ctx.translate(450,260);
    ctx.beginPath(); ctx.arc(0,0,180,0,Math.PI*2); ctx.fillStyle='#1c2b44'; ctx.fill();
    ctx.beginPath(); ctx.arc(0,0,180,winStart,winStart+winArc); ctx.lineTo(0,0); ctx.closePath();
    ctx.fillStyle='#ffd84a'; ctx.fill();
    ctx.rotate(angle);
    ctx.strokeStyle='#fff'; ctx.lineWidth=5; ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(170,0); ctx.stroke();
    ctx.restore();
    raf=requestAnimationFrame(frame);
   }
   raf=requestAnimationFrame(frame);
   const click=()=>{
    if(stopped)return; stopped=true;
    const norm=((angle%(Math.PI*2))+Math.PI*2)%(Math.PI*2);
    const diff=((norm-winStart)%(Math.PI*2)+Math.PI*2)%(Math.PI*2);
    if(diff<=winArc)winLevel(); else loseLevel();
   };
   addListener(c,'click',click);
   countdown(lerp(lv,10,6),()=>{if(!stopped)loseLevel()});
  }

