  function tacticalRead(lv){
   /* V1230.28 — "Read the Press": a distinct football game for the Tactical Decision Lab, separate
      from the Breakthrough Run dribbling game in the Football Lab. This is about reading the pitch,
      not steering a ball: teammates around you flip between open (green ring) and covered (red ring)
      on their own clock, faster and more often as the level rises, and a wrong pick ends the level
      immediately — exactly the split-second pass-or-don't decision a real tactical read is. */
   const n=Math.round(lerp(lv,3,6));
   const neededStreak=Math.round(lerp(lv,3,6));
   const flipInterval=lerp(lv,1500,430);
   const flipChance=lerp(lv,0.45,0.85);
   const radius=190;
   const mates=[];
   for(let i=0;i<n;i++){
    const angle=(Math.PI*2*i/n)-Math.PI/2;
    mates.push({x:450+Math.cos(angle)*radius,y:270+Math.sin(angle)*radius,open:Math.random()<0.4});
   }
   let streak=0;
   const render=()=>{
    clear();
    ctx.strokeStyle='#2f6e45'; ctx.lineWidth=3; ctx.strokeRect(40,40,820,420);
    mates.forEach(p=>{
     ctx.strokeStyle=ctx.fillStyle='#4a5a84';
     ctx.beginPath(); ctx.moveTo(450,270); ctx.lineTo(p.x,p.y); ctx.strokeStyle='rgba(255,255,255,.08)'; ctx.lineWidth=2; ctx.stroke();
    });
    mates.forEach(p=>{
     ctx.strokeStyle=p.open?'#5de0b0':'#ff5a72'; ctx.lineWidth=4;
     ctx.beginPath(); ctx.arc(p.x,p.y,24,0,7); ctx.stroke();
     ctx.fillStyle='#1c2b44'; ctx.beginPath(); ctx.arc(p.x,p.y,20,0,7); ctx.fill();
    });
    ctx.fillStyle='#ffd84a'; ctx.beginPath(); ctx.arc(450,270,18,0,7); ctx.fill();
    txt(`${streak}/${neededStreak}`,450,30,22);
   };
   render();
   addInterval(()=>{mates.forEach(p=>{if(Math.random()<flipChance)p.open=!p.open}); render()},flipInterval);
   const click=(e)=>{
    const p=point(e);
    for(const slot of mates){
     if(Math.hypot(p.x-slot.x,p.y-slot.y)<26){
      if(slot.open){streak++; render(); if(streak>=neededStreak){winLevel();return}}
      else{loseLevel();return}
      break;
     }
    }
   };
   addListener(c,'click',click);
   countdown(lerp(lv,15,7),()=>loseLevel());
  }

  function dailyMix(lv){
   const day=new Date().toISOString().slice(0,10);
   let seed=0; for(const ch of day)seed=(seed*31+ch.charCodeAt(0))>>>0;
   const pool=['reaction','mathGame','memory','focus','pattern'];
   const pick=(n)=>pool[(seed+n*7)%pool.length];
   let phase,localLv;
   if(lv<=3){phase=pick(0);localLv=Math.round(lerp(lv,1,4))}
   else if(lv<=6){phase=pick(1);localLv=Math.round(lerp(lv-3,4,7))}
   else{phase=pick(2);localLv=Math.round(lerp(lv-6,7,10))}
   archFns[phase](localLv);
  }

  const archFns={football,tacticalRead,mathGame,science,memory,logic,pattern,visual,codeFix,reaction,focus,strategy,probability,whoami,language,lateral,dailyMix};
  const archMap={football:'football',football_intelligence:'tacticalRead',math:'mathGame',science:'science',memory:'memory',memory_focus:'memory',memory_v22:'memory',logic:'logic',logic_extreme:'logic',iq:'pattern',pattern_v18:'pattern',visual_v22:'visual',code_v22:'codeFix',reaction:'reaction',focus_v18:'focus',strategy:'strategy',probability_v22:'probability',daily:'dailyMix',whoami:'whoami',language_v22:'language',lateral_v22:'lateral',forensic:'codeFix',horror:'reaction'};

