 submitWorld(el,q){if(this.locked)return;this.locked=true;clearInterval(this.timer);const choices=q.a||q.options||q.choices||q.answers;const value=el?.dataset?.i!==undefined?(choices||[])[Number(el.dataset.i)]:el?.querySelector?.('input')?.value;const ok=this.answer(q,value);try{(this.answersLog=this.answersLog||[]).push({id:q.id,value});}catch(_){}if(this.run.scored){if(ok){this.correct++;this.streak++;this.best=Math.max(this.best,this.streak);this.score+=Math.max(10,55+difficulty(q)*5)}else this.streak=0;}else{this.streak=0;}try{audio()[ok?'correct':'wrong']?.()}catch(_){}const f=this.mount.querySelector('.zrw-feedback');if(f)f.textContent=ok?t('challengesFeedbackCorrect'):t('challengesFeedbackWrong');setTimeout(()=>this.advanceWorld(ok,false),650)},
